<?php
require_once __DIR__.'/accounting-core.php';
class CoReports {
 private $s;
 public function __construct(CoService $service){$this->s=$service;}
 public function range($company,array $p){$this->s->permit($company);$from=coDate($p['from']??substr(coNow(),0,7).'-01');$to=coDate($p['to']??substr(coNow(),0,10));if($from>$to||((new DateTime($from))->diff(new DateTime($to))->days)>3660)throw new InvalidArgumentException('Rango inválido; máximo diez años.');return [$from,$to,empty($p['branchId'])?null:(int)$p['branchId']];}
 public function trial($company,array $p){list($from,$to,$branch)=$this->range($company,$p);$args=[$from,$from,$from,$to,$from,$to,$company,$to];$where='';if($branch){$where=' AND e.BranchId=?';$args[]=$branch;}if(!empty($p['account'])){$where.=' AND l.Account=?';$args[]=coText((string)$p['account'],20,true);}
  return $this->s->rows("SELECT a.Code,a.Name,a.Nature,a.Class,a.ReportGroup,SUM(CASE WHEN e.EntryDate<? THEN l.Debit ELSE 0 END) OpeningDebit,SUM(CASE WHEN e.EntryDate<? THEN l.Credit ELSE 0 END) OpeningCredit,SUM(CASE WHEN e.EntryDate BETWEEN ? AND ? THEN l.Debit ELSE 0 END) Debit,SUM(CASE WHEN e.EntryDate BETWEEN ? AND ? THEN l.Credit ELSE 0 END) Credit,SUM(l.Debit-l.Credit) Balance FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId JOIN Co_Account a ON a.CompanyId=l.CompanyId AND a.Code=l.Account WHERE l.CompanyId=? AND e.Status='posted' AND e.EntryDate<=?".$where.' GROUP BY a.Code ORDER BY a.Code',$args);
 }
 public function journal($company,array $p){list($from,$to,$branch)=$this->range($company,$p);$args=[$company,$from,$to];$where='';if($branch){$where.=' AND e.BranchId=?';$args[]=$branch;}if(!empty($p['account'])){$where.=' AND l.Account=?';$args[]=$p['account'];}
  $rows=$this->s->rows("SELECT e.Id,e.EntryDate,e.Period,e.Number,e.BranchId,e.Currency,e.ExchangeRate,e.Document,e.ElectronicData,e.Memo,e.SourceType,e.SourceId,e.ReversalOf,l.Id LineId,l.Account,a.Name AccountName,l.Debit,l.Credit,l.OriginalDebit,l.OriginalCredit,l.PartyType,l.PartyId,l.CashFlow FROM Co_Entry e JOIN Co_Line l ON l.CompanyId=e.CompanyId AND l.EntryId=e.Id JOIN Co_Account a ON a.CompanyId=l.CompanyId AND a.Code=l.Account WHERE e.CompanyId=? AND e.Status='posted' AND e.EntryDate BETWEEN ? AND ?".$where.' ORDER BY e.EntryDate,e.Number,l.Id LIMIT 50001',$args);if(count($rows)>50000)throw new InvalidArgumentException('Reduce el rango: el detalle supera 50000 líneas. Los estados financieros admiten rangos consolidados mayores.');return $rows;
 }
 public function ledger($company,array $p){$rows=$this->journal($company,$p);$opening=[];foreach($this->trial($company,$p) as $a)$opening[$a['Code']]=(int)$a['OpeningDebit']-(int)$a['OpeningCredit'];usort($rows,function($a,$b){return strcmp($a['Account'],$b['Account'])?:strcmp($a['EntryDate'],$b['EntryDate'])?:((int)$a['Number']<=>(int)$b['Number'])?:((int)$a['LineId']<=>(int)$b['LineId']);});foreach($rows as &$r){$opening[$r['Account']]=($opening[$r['Account']]??0)+(int)$r['Debit']-(int)$r['Credit'];$r['RunningBalance']=$opening[$r['Account']];}return $rows;}
 public function auxiliary($company,array $p){list($from,$to,$branch)=$this->range($company,$p);$args=[$from,$from,$from,$to,$from,$to,$company,$to];$where='';if($branch){$where.=' AND e.BranchId=?';$args[]=$branch;}if(!empty($p['account'])){$where.=' AND l.Account=?';$args[]=$p['account'];}return $this->s->rows("SELECT l.Account,l.PartyType,l.PartyId,SUM(CASE WHEN e.EntryDate<? THEN l.Debit ELSE 0 END) OpeningDebit,SUM(CASE WHEN e.EntryDate<? THEN l.Credit ELSE 0 END) OpeningCredit,SUM(CASE WHEN e.EntryDate BETWEEN ? AND ? THEN l.Debit ELSE 0 END) Debit,SUM(CASE WHEN e.EntryDate BETWEEN ? AND ? THEN l.Credit ELSE 0 END) Credit,SUM(l.Debit-l.Credit) Balance FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId WHERE l.CompanyId=? AND e.Status='posted' AND e.EntryDate<=?".$where.' GROUP BY l.Account,l.PartyType,l.PartyId ORDER BY l.Account,l.PartyType,l.PartyId',$args);}
 public function statements($company,array $p){unset($p['account']);$trial=$this->trial($company,$p);$groups=[];$assets=0;$liabilities=0;$equity=0;$retained=0;$income=0;$expense=0;$movementEquity=0;$openingEquity=0;$openingProfit=0;
  foreach($trial as $a){$balance=(int)$a['Balance'];$movement=(int)$a['Debit']-(int)$a['Credit'];$opening=(int)$a['OpeningDebit']-(int)$a['OpeningCredit'];$key=$a['ReportGroup'];if(!isset($groups[$key]))$groups[$key]=['group'=>$key,'class'=>$a['Class'],'opening'=>0,'movement'=>0,'balance'=>0];$sign=in_array($a['Class'],['liability','equity','income'],true)?-1:1;$groups[$key]['opening']+=$sign*$opening;$groups[$key]['movement']+=$sign*$movement;$groups[$key]['balance']+=$sign*$balance;
   if($a['Class']==='asset')$assets+=$balance;if($a['Class']==='liability')$liabilities-=$balance;if($a['Class']==='equity'){$equity-=$balance;$movementEquity-=$movement;$openingEquity-=$opening;}if($a['Class']==='income'){$income-=$movement;$retained-=$balance;$openingProfit-=$opening;}if($a['Class']==='expense'){$expense+=$movement;$retained-=$balance;$openingProfit-=$opening;}
  }
  list($from,$to,$branch)=$this->range($company,$p);$args=[$company,$from,$to];$where='';if($branch){$where=' AND e.BranchId=?';$args[]=$branch;}$aggregates=$this->s->rows("SELECT l.Account,l.CashFlow,e.SourceType,SUM(l.Debit) Debit,SUM(l.Credit) Credit FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId WHERE l.CompanyId=? AND e.Status='posted' AND e.EntryDate BETWEEN ? AND ?".$where.' GROUP BY l.Account,l.CashFlow,e.SourceType',$args);$accountMap=[];foreach($trial as $a)$accountMap[$a['Code']]=$a;
  $income=0;$expense=0;$movementEquity=0;foreach($aggregates as $line){if($line['SourceType']==='closing')continue;$a=$accountMap[$line['Account']];if($a['Class']==='income')$income+=(int)$line['Credit']-(int)$line['Debit'];if($a['Class']==='expense')$expense+=(int)$line['Debit']-(int)$line['Credit'];if($a['Class']==='equity')$movementEquity+=(int)$line['Credit']-(int)$line['Debit'];}
  $flows=['operating'=>0,'investing'=>0,'financing'=>0,'fx'=>0,'unclassified'=>0];$cashOpening=0;$cashClosing=0;
  foreach($trial as $a)if(in_array($a['ReportGroup'],['cash','bank'],true)){$cashOpening+=(int)$a['OpeningDebit']-(int)$a['OpeningCredit'];$cashClosing+=(int)$a['Balance'];}
  foreach($aggregates as $line){$account=$accountMap[$line['Account']];if(!in_array($account['ReportGroup'],['cash','bank'],true))continue;$flows[$line['CashFlow']?:'unclassified']+=(int)$line['Debit']-(int)$line['Credit'];}
  $net=$income-$expense;$openingResult=$openingProfit;
  return ['groups'=>array_values($groups),'position'=>['assets'=>$assets,'liabilities'=>$liabilities,'equity'=>$equity,'unclosedResult'=>$retained,'difference'=>$assets-$liabilities-$equity-$retained],'results'=>['income'=>$income,'expenses'=>$expense,'net'=>$net],'cashFlow'=>['opening'=>$cashOpening,'closing'=>$cashClosing,'flows'=>$flows,'difference'=>$cashClosing-$cashOpening-array_sum($flows)],'equity'=>['opening'=>$openingEquity+$openingResult,'capitalMovements'=>$movementEquity,'periodResult'=>$net,'closing'=>$equity+$retained]];
 }
 public function comparative($company,array $p){list($from,$to,$branch)=$this->range($company,$p);$cursor=new DateTimeImmutable(substr($from,0,7).'-01');$rows=[];while($cursor->format('Y-m-d')<=$to){$f=max($from,$cursor->format('Y-m-d'));$t=min($to,$cursor->format('Y-m-t'));$r=$this->statements($company,['from'=>$f,'to'=>$t,'branchId'=>$branch]);$rows[]=['period'=>$cursor->format('Y-m'),'income'=>$r['results']['income'],'expenses'=>$r['results']['expenses'],'net'=>$r['results']['net'],'assets'=>$r['position']['assets'],'liabilities'=>$r['position']['liabilities'],'equity'=>$r['position']['equity']+$r['position']['unclosedResult']];$cursor=$cursor->modify('+1 month');}return $rows;}
 public function annual($company,array $p){$groups=[];foreach($this->comparative($company,$p) as $row){$year=substr($row['period'],0,4);if(!isset($groups[$year]))$groups[$year]=['period'=>$year,'income'=>0,'expenses'=>0,'net'=>0,'assets'=>0,'liabilities'=>0,'equity'=>0];foreach(['income','expenses','net'] as $key)$groups[$year][$key]+=$row[$key];foreach(['assets','liabilities','equity'] as $key)$groups[$year][$key]=$row[$key];}return array_values($groups);}
 public function tax($company,array $p){list($from,$to,$branch)=$this->range($company,$p);$args=[$company,substr($from,0,7),substr($to,0,7)];$where='';if($branch){$where=' AND e.BranchId=?';$args[]=$branch;}
  $rows=$this->s->rows("SELECT t.*,e.Document,e.EntryDate,e.Currency,e.ExchangeRate FROM Co_TaxDocument t JOIN Co_Entry e ON e.CompanyId=t.CompanyId AND e.Id=t.EntryId WHERE t.CompanyId=? AND t.TaxPeriod BETWEEN ? AND ? AND e.Status='posted'".$where.' ORDER BY t.IssueDate,t.Id',$args);$summary=['sales'=>0,'purchases'=>0,'debitIgv'=>0,'creditIgv'=>0,'withholding'=>0,'perception'=>0,'detraction'=>0,'netIgvBeforeCarry'=>0];
  foreach($rows as &$r){if($r['State']==='void'){foreach(['Taxable','Exempt','Unaffected','FreeAmount','FreeIgv','Igv','OtherTaxes','Total','Withholding','Perception','Detraction'] as $key)$r[$key]=0;}$sign=(int)$r['Sign'];$summary[$r['Kind']==='sale'?'sales':'purchases']+=$sign*(int)$r['Total'];if($r['Kind']==='sale')$summary['debitIgv']+=$sign*((int)$r['Igv']+(int)$r['FreeIgv']);elseif($r['CreditEligible'])$summary['creditIgv']+=$sign*(int)$r['Igv'];foreach(['withholding'=>'Withholding','perception'=>'Perception','detraction'=>'Detraction'] as $k=>$column)$summary[$k]+=$sign*(int)$r[$column];}unset($r);$summary['netIgvBeforeCarry']=$summary['debitIgv']-$summary['creditIgv'];return ['documents'=>$rows,'summary'=>$summary,'note'=>'Importes según documentos revisados; no aplica saldos a favor, prorrata, renta ni compensaciones automáticamente.'];
 }
 public function dashboard($company,array $p){$statements=$this->statements($company,$p);$args=[$company];$pending=$this->s->rows("SELECT Status,COUNT(*) Count FROM Co_Entry WHERE CompanyId=? AND Status IN ('draft','reviewed','approved') GROUP BY Status",$args);$sources=$this->s->rows("SELECT State,COUNT(*) Count FROM Co_Source WHERE CompanyId=? AND State IN ('pending','conflict') GROUP BY State",$args);$unbalanced=$this->s->rows('SELECT e.Id FROM Co_Entry e JOIN Co_Line l ON l.CompanyId=e.CompanyId AND l.EntryId=e.Id WHERE e.CompanyId=? GROUP BY e.Id HAVING SUM(l.Debit)<>SUM(l.Credit)',$args);
  $totals=['receivable'=>0,'payable'=>0,'cash'=>0,'bank'=>0];foreach($this->trial($company,$p) as $a)if(array_key_exists($a['ReportGroup'],$totals))$totals[$a['ReportGroup']]+=(in_array($a['ReportGroup'],['payable'],true)?-1:1)*(int)$a['Balance'];return ['statements'=>$statements,'balances'=>$totals,'tax'=>$this->tax($company,$p)['summary'],'pending'=>$pending,'pendingSources'=>$sources,'unbalanced'=>$unbalanced,'periods'=>$this->s->rows('SELECT * FROM Co_Period WHERE CompanyId=? ORDER BY Period DESC LIMIT 36',$args)];}
 public function externalRegister($company,array $p){$this->s->permit($company,'reconcile');$period=coPeriod($p['period']??'');$kind=$p['kind']??'';$rows=$p['rows']??[];if(!in_array($kind,['sale','purchase'],true)||!count($rows)||count($rows)>10000)throw new InvalidArgumentException('Registro de conciliación inválido.');return $this->s->transaction(function()use($company,$period,$kind,$rows){foreach($rows as $r){$key=coText($r['documentKey']??'',150,true);$this->s->exec('INSERT INTO Co_ExternalRegister(CompanyId,Period,Kind,DocumentKey,Total,Igv,Payload) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE Total=VALUES(Total),Igv=VALUES(Igv),Payload=VALUES(Payload)',[$company,$period,$kind,$key,coMoney($r['total']??'',true),coMoney($r['igv']??'0',true),coJson($r)]);}$this->s->audit($company,'import','external-register',$period,['kind'=>$kind,'count'=>count($rows)]);return ['count'=>count($rows)];});}
 public function reconcileTax($company,array $p){$period=coPeriod($p['period']??'');$this->s->permit($company);$local=$this->tax($company,['from'=>$period.'-01','to'=>(new DateTime($period.'-01'))->format('Y-m-t')])['documents'];$groups=[];foreach($local as $d){$key=$d['Kind'].'|'.$d['PartyDoc'].'|'.$d['DocType'].'|'.$d['Series'].'|'.$d['DocNumber'];$groups[$key]=['key'=>$key,'localTotal'=>(int)$d['Total']*(int)$d['Sign'],'localIgv'=>((int)$d['Igv']+(int)$d['FreeIgv'])*(int)$d['Sign'],'externalTotal'=>null,'externalIgv'=>null];}
  foreach($this->s->rows('SELECT * FROM Co_ExternalRegister WHERE CompanyId=? AND Period=?',[$company,$period]) as $r){$key=$r['Kind'].'|'.$r['DocumentKey'];if(!isset($groups[$key]))$groups[$key]=['key'=>$key,'localTotal'=>null,'localIgv'=>null];$groups[$key]['externalTotal']=(int)$r['Total'];$groups[$key]['externalIgv']=(int)$r['Igv'];}
  foreach($groups as &$r){$r['externalTotal']=$r['externalTotal']??null;$r['externalIgv']=$r['externalIgv']??null;$r['state']=$r['localTotal']===null?'only_external':($r['externalTotal']===null?'only_local':($r['localTotal']===$r['externalTotal']&&$r['localIgv']===$r['externalIgv']?'matched':'difference'));}return array_values($groups);
 }
}
